def comps(board,color=8):
 seen=set(); out=[]
 for y in range(64):
  for x in range(64):
   if board[y][x]==color and (x,y) not in seen:
    st=[(x,y)];seen.add((x,y));cc=[]
    while st:
     a,b=st.pop();cc.append((a,b))
     for p,q in ((a+1,b),(a-1,b),(a,b+1),(a,b-1)):
      if 0<=p<64 and 0<=q<64 and board[q][p]==color and (p,q) not in seen:seen.add((p,q));st.append((p,q))
    out.append((min(a for a,b in cc),min(b for a,b in cc),max(a for a,b in cc),max(b for a,b in cc)))
 return out
